{+        target.parent.mkdir(parents=True, exist_ok=True)+}
{+        target.write_text("line\n" * lines, encoding="utf-8")+}
{+        self.git(repo, "add", path)+}
{+        self.git(repo, "commit", "-m", f"add {path}")+}

